/// <reference lib="webworker" />
/**
 * Service worker: lets the site be used offline without delaying updates.
 *
 * - JS and CSS generated by the build have a hash in their name (immutable):
 *   they are precached and served from the cache.
 * - Everything else (page, index.json, Bibles, manifest) is network-first:
 *   the cache is only used offline. The request with `cache: 'no-cache'` makes
 *   the server answer 304 when nothing changed, without resending the Bibles.
 *   The Bibles are in another origin (the Blob store), which is handled the same way.
 * - Every SPA navigation (/por/ave-maria/jo/3,16, /planos...) gets the same
 *   page, kept in a single cache entry.
 */
import { clientsClaim } from 'workbox-core';
import { cleanupOutdatedCaches, matchPrecache, precache, precacheAndRoute } from 'workbox-precaching';
import { NavigationRoute, registerRoute } from 'workbox-routing';
import { NetworkFirst } from 'workbox-strategies';

declare const self: ServiceWorkerGlobalScope;
/** Origin of the Blob store that holds the Bibles, injected by vite.config.ts from settings.json. */
declare const __BIBLES_ORIGIN__: string;

/** Cache used by the service worker that predates the migration to Vite. */
const LEGACY_CACHE = 'abra-sua-biblia-v1';
const RUNTIME_CACHE = 'abra-sua-biblia-runtime';
const APP_SHELL = 'index.html';
/** URL used to fetch the page on any navigation (Vercel serves it on every path). */
const APP_SHELL_URL = '/';
/** Navigations that are not SPA screens: published files. */
const NOT_SPA = [/^\/assets\//, /^\/[^/]+\.[a-z]+$/i];

void self.skipWaiting();
clientsClaim();
cleanupOutdatedCaches();

self.addEventListener('activate', (event) => {
    event.waitUntil(caches.delete(LEGACY_CACHE));
});

const manifest = self.__WB_MANIFEST;
const isAppShell = (entry: (typeof manifest)[number]) =>
    (typeof entry === 'string' ? entry : entry.url) === APP_SHELL;

// The page is precached only as an offline fallback; it is not served from the precache.
precache(manifest.filter(isAppShell));
precacheAndRoute(manifest.filter((entry) => !isAppShell(entry)));

const networkFirst = new NetworkFirst({
    cacheName: RUNTIME_CACHE,
    fetchOptions: { cache: 'no-cache' },
});

registerRoute(
    new NavigationRoute(
        async ({ event }) => {
            try {
                return await networkFirst.handle({ event, request: APP_SHELL_URL });
            } catch {
                return (await matchPrecache(APP_SHELL)) ?? Response.error();
            }
        },
        { denylist: NOT_SPA },
    ),
);

registerRoute(
    ({ request, url }) =>
        request.method === 'GET' && (url.origin === self.location.origin || url.origin === __BIBLES_ORIGIN__),
    networkFirst,
);
